(function () {
  'use strict';

  const K = {
    basket: 'chto-prigotovit/v1',
    ing: 'chto-prigotovit/v1/ing',
    rec: 'chto-prigotovit/v1/recipes',
    theme: 'chto-prigotovit/v1/theme',
    lang: 'chto-prigotovit/v1/lang',
  };
  /* Ключи данных всегда русские: по ним связаны рецепты, свои продукты и корзина.
     Переключение языка меняет только подписи, сохранённое не трогает. */
  const OWN_CAT = 'Свои продукты';
  const BASESET = new Set(BASE);
  const ALL = '*all*';
  const MINE = '*mine*';

  const norm = s => String(s).toLowerCase().replace(/ё/g, 'е').trim();
  const esc = s => String(s).replace(/[&<>"]/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));
  const clamp = (v, a, b) => Math.min(b, Math.max(a, v));

  function load(key, fallback) {
    try { const v = JSON.parse(localStorage.getItem(key) || 'null'); return v == null ? fallback : v; }
    catch (e) { return fallback; }
  }
  function store(key, val) { try { localStorage.setItem(key, JSON.stringify(val)); } catch (e) {} }

  /* ---------- язык ---------- */
  const saved = load(K.lang, null);
  const systemLang = typeof navigator !== 'undefined' && navigator.language
    ? (navigator.language.toLowerCase().startsWith('ru') ? 'ru' : 'en')
    : 'ru';
  let lang = saved === 'ru' || saved === 'en' ? saved : systemLang;
  let UI = I18N.ui[lang];

  /** Строка интерфейса. %1, %2 … заменяются на аргументы как есть — экранирует вызывающий. */
  function t(key) {
    let s = UI[key] != null ? UI[key] : key;
    for (let i = 1; i < arguments.length; i++) s = s.split('%' + i).join(arguments[i]);
    return s;
  }

  /** Форма числительного: в русском три варианта, в английском два. */
  function plural(n, key) {
    const forms = UI[key];
    if (lang !== 'ru') return forms[n === 1 ? 0 : 1];
    const a = Math.abs(n) % 100, b = a % 10;
    return forms[a > 10 && a < 20 ? 2 : b === 1 ? 0 : b > 1 && b < 5 ? 1 : 2];
  }
  const withN = (n, key) => n + ' ' + plural(n, key);

  /* Подписи данных: в русском это сам ключ, в английском — перевод из словаря.
     Свои продукты и рецепты не переводятся, показываются как введены. */
  const ingName = key => (lang === 'ru' ? key : (I18N.en.ing[key] || key));
  const sectionName = s => (lang === 'ru' ? s
    : (I18N.en.sec[s] || (s === OWN_CAT ? t('own_section') : s)));
  const typeName = c => (lang === 'ru' ? c : (I18N.en.typ[c] || c));
  const qtyText = q => (lang === 'ru' || !q ? q : (I18N.en.qty[q] || q));
  const trOf = r => (lang === 'ru' || r.own ? null : I18N.en.rec[r.n]);
  const recName = r => { const x = trOf(r); return x ? x.n : r.n; };
  const recSteps = r => { const x = trOf(r); return x ? x.st : r.st; };
  const recNote = r => { const x = trOf(r); return x && x.note ? x.note : (x ? null : r.note); };
  const synOf = it => (lang === 'ru' ? it.syn : (I18N.en.syn[it.name] || []));

  /** Введённое человеком название продукта — обратно в ключ каталога, на любом языке. */
  function canonIng(text) {
    const n = norm(text);
    let hit = null;
    ING.forEach((it, key) => {
      if (!hit && (norm(key) === n || norm(ingName(key)) === n)) hit = key;
    });
    return hit;
  }

  /** То же для типа блюда: «Soup» и «Суп» — один и тот же тип. */
  function canonType(text) {
    const n = norm(text);
    const hit = Object.keys(I18N.en.typ).find(ru => norm(ru) === n || norm(I18N.en.typ[ru]) === n);
    return hit || text;
  }

  /* ---------- состояние ---------- */
  let customIng = load(K.ing, []);                 // [{name, cat}]
  let customRecipes = load(K.rec, []);             // [{id, own, n, c, t, s, g, st, note}]
  let selected = new Set(load(K.basket, null) || BASE);

  let filterType = ALL, filterTime = 0, onlyReady = false;
  let cursor = -1, hits = [], editingId = null;

  const saveBasket = () => store(K.basket, [...selected]);

  /* ---------- индекс продуктов ---------- */
  const ING = new Map();                           // ключ -> {name, cat, syn, own}
  function buildIndex() {
    ING.clear();
    CATALOG.forEach(([cat, items]) => items.forEach(([name, syn]) => ING.set(name, { name, cat, syn: syn || [] })));
    customIng.forEach(({ name, cat }) => ING.set(name, { name, cat: cat || OWN_CAT, syn: [], own: true }));
  }

  /* Каталог для левой колонки: встроенные разделы + свои продукты в их разделах. */
  function catalogView() {
    const map = new Map(CATALOG.map(([c, items]) => [c, items.map(([n]) => n)]));
    customIng.forEach(({ name, cat }) => {
      const c = cat || OWN_CAT;
      if (!map.has(c)) map.set(c, []);
      if (!map.get(c).includes(name)) map.get(c).push(name);
    });
    return [...map.entries()];
  }

  const allRecipes = () => customRecipes.concat(RECIPES);
  const types = () => [...new Set(allRecipes().map(r => r.c))];
  const findRecipe = id => customRecipes.find(r => r.id === id);

  /* ---------- элементы ---------- */
  const $ = id => document.getElementById(id);
  const qInput = $('q'), sugBox = $('suggest'), basket = $('basket'), basketEmpty = $('basketEmpty'),
        basketCount = $('basketCount'), catsBox = $('cats'), out = $('out'),
        typeTabs = $('typeTabs'), timeTabs = $('timeTabs'), onlyReadyBox = $('onlyReady');

  /* ---------- общая перерисовка ---------- */
  function renderAll() {
    buildIndex();
    if (filterType !== ALL && filterType !== MINE && !types().includes(filterType)) filterType = ALL;
    if (filterType === MINE && !customRecipes.length) filterType = ALL;
    $('statTotal').textContent = allRecipes().length;
    $('statIng').textContent = ING.size;
    $('ingList').innerHTML = [...ING.keys()]
      .map(n => `<option value="${esc(ingName(n))}"></option>`).join('');
    $('typeList').innerHTML = types()
      .map(c => `<option value="${esc(typeName(c))}"></option>`).join('');
    renderTabs();
    renderBasket();
    renderCats();
    renderResults();
  }

  /* ---------- корзина ---------- */
  function add(name) {
    if (!name) return;
    selected.add(name); saveBasket(); renderBasket(); renderCats(); renderResults();
  }
  function remove(name) {
    selected.delete(name); saveBasket(); renderBasket(); renderCats(); renderResults();
  }

  function renderBasket() {
    const list = [...selected].sort((a, b) => {
      const ab = BASESET.has(a), bb = BASESET.has(b);
      if (ab !== bb) return ab ? 1 : -1;
      return ingName(a).localeCompare(ingName(b), lang);
    });
    basketCount.textContent = list.length;
    basketEmpty.hidden = list.length > 0;
    basket.innerHTML = list.map(n =>
      `<span class="chip${BASESET.has(n) ? ' chip--base' : ''}">${esc(ingName(n))}` +
      `<button class="chip__x" type="button" data-del="${esc(n)}" ` +
      `aria-label="${esc(t('remove_from_basket', ingName(n)))}">×</button></span>`
    ).join('');
  }

  basket.addEventListener('click', e => {
    const b = e.target.closest('[data-del]');
    if (b) remove(b.dataset.del);
  });

  $('clearBtn').addEventListener('click', () => {
    selected = new Set(BASE); saveBasket(); renderBasket(); renderCats(); renderResults();
  });

  /* ---------- категории ---------- */
  function renderCats() {
    catsBox.innerHTML = catalogView().map(([cat, items]) => {
      const on = items.filter(n => selected.has(n)).length;
      const open = catsBox.querySelector(`details[data-cat="${esc(cat)}"]`)?.open;
      const pills = items.map(n => {
        const pill = `<button class="pill${selected.has(n) ? ' is-on' : ''}" type="button" ` +
          `data-tog="${esc(n)}">${esc(ingName(n))}</button>`;
        return ING.get(n)?.own
          ? `<span class="own-ing">${pill}<button class="pill__del" type="button" data-del-ing="${esc(n)}" ` +
            `title="${esc(t('delete_product'))}" aria-label="${esc(t('delete_product'))}">×</button></span>`
          : pill;
      }).join('');
      return `<details class="cat" data-cat="${esc(cat)}"${open ? ' open' : ''}>
        <summary class="cat__btn"><span class="cat__arrow">▸</span>${esc(sectionName(cat))}
          <span class="cat__count${on ? ' is-on' : ''}">${on ? on + ' / ' : ''}${items.length}</span></summary>
        <div class="cat__body">${pills}</div></details>`;
    }).join('');
  }

  catsBox.addEventListener('click', e => {
    const del = e.target.closest('[data-del-ing]');
    if (del) { deleteIngredient(del.dataset.delIng); return; }
    const b = e.target.closest('[data-tog]');
    if (!b) return;
    const n = b.dataset.tog;
    selected.has(n) ? remove(n) : add(n);
  });

  /* ---------- автодополнение ---------- */
  function search(raw) {
    const q = norm(raw);
    if (!q) return [];
    const res = [];
    ING.forEach(it => {
      const shown = ingName(it.name);
      const n = norm(shown);
      let rank = -1, via = null;
      if (n.startsWith(q)) rank = 0;
      else if (n.split(' ').some(w => w.startsWith(q))) rank = 1;
      else if (n.includes(q)) rank = 2;
      else {
        const hit = synOf(it).find(s => norm(s).includes(q));
        if (hit) { rank = 3; via = hit; }
        else if (lang !== 'ru' && norm(it.name).includes(q)) rank = 4;  // поиск по русскому названию
      }
      if (rank >= 0) res.push({ it, shown, rank, via });
    });
    // при равном ранге вперёд идёт более короткое название: «помидоры» раньше «томатной пасты»
    res.sort((a, b) =>
      a.rank - b.rank || a.shown.length - b.shown.length || a.shown.localeCompare(b.shown, lang));
    return res.slice(0, 8);
  }

  function highlight(name, q) {
    const i = norm(name).indexOf(norm(q));
    if (i < 0) return esc(name);
    return esc(name.slice(0, i)) + '<mark>' + esc(name.slice(i, i + q.length)) + '</mark>' + esc(name.slice(i + q.length));
  }

  function renderSuggest() {
    const raw = qInput.value.trim();
    hits = search(raw);
    const custom = raw.length > 1 && !hits.some(h => norm(h.shown) === norm(raw) || norm(h.it.name) === norm(raw));
    if (!hits.length && !custom) { closeSuggest(); return; }

    sugBox.innerHTML = hits.map((h, i) =>
      `<li role="option" data-i="${i}" aria-selected="${i === cursor}" class="${selected.has(h.it.name) ? 'is-added' : ''}">
        <span>${highlight(h.shown, raw)}${h.via ? ` <i style="color:var(--ink-3);font-style:normal;font-size:11px">· ${esc(h.via)}</i>` : ''}</span>
        <span class="s-cat">${selected.has(h.it.name) ? esc(t('in_basket')) : esc(sectionName(h.it.cat))}</span>
      </li>`
    ).join('') + (custom
      ? `<li role="option" data-i="${hits.length}" aria-selected="${cursor === hits.length}">
          <span class="s-new">${esc(t('add_custom', raw))}</span><span class="s-cat">${esc(t('own_short'))}</span></li>`
      : '');

    sugBox.hidden = false;
    qInput.setAttribute('aria-expanded', 'true');
  }

  function closeSuggest() {
    sugBox.hidden = true; sugBox.innerHTML = ''; cursor = -1;
    qInput.setAttribute('aria-expanded', 'false');
  }

  function pick(i) {
    const raw = qInput.value.trim();
    if (i < hits.length) add(hits[i].it.name);
    else { addIngredient(raw, OWN_CAT); add(raw); }
    qInput.value = '';
    closeSuggest();
    qInput.focus();
  }

  qInput.addEventListener('input', () => { cursor = -1; renderSuggest(); });
  qInput.addEventListener('focus', () => { if (qInput.value.trim()) renderSuggest(); });
  qInput.addEventListener('blur', () => setTimeout(closeSuggest, 120));
  qInput.addEventListener('keydown', e => {
    const total = sugBox.querySelectorAll('li').length;
    if (e.key === 'ArrowDown' || e.key === 'ArrowUp') {
      if (!total) return;
      e.preventDefault();
      cursor = e.key === 'ArrowDown' ? (cursor + 1) % total : (cursor - 1 + total) % total;
      renderSuggest();
    } else if (e.key === 'Enter') {
      e.preventDefault();
      if (total) pick(cursor >= 0 ? cursor : 0);
    } else if (e.key === 'Escape') closeSuggest();
  });
  sugBox.addEventListener('mousedown', e => {
    const li = e.target.closest('li');
    if (li) { e.preventDefault(); pick(+li.dataset.i); }
  });

  /* ---------- свои продукты ---------- */
  function addIngredient(name, cat) {
    name = String(name).trim();
    if (!name) return null;
    const exists = canonIng(name);
    if (exists) return exists;
    customIng.push({ name, cat: cat || OWN_CAT });
    store(K.ing, customIng);
    buildIndex();
    return name;
  }

  function usedInOwnRecipes(name) {
    return customRecipes.filter(r =>
      r.g.some(([id, q, o]) => id === name || (o && o.s || []).includes(name))).map(r => recName(r));
  }

  function deleteIngredient(name) {
    const used = usedInOwnRecipes(name);
    if (used.length) {
      alertBox(t('ing_in_use', ingName(name), used.join(', ')));
      return;
    }
    customIng = customIng.filter(i => i.name !== name);
    selected.delete(name);
    store(K.ing, customIng); saveBasket();
    renderAll();
    renderMine();
  }

  /* ---------- подбор рецептов ---------- */
  function analyse(r) {
    const have = [], need = [], nice = [];
    r.g.forEach(([id, q, o]) => {
      const opt = o || {};
      const direct = selected.has(id);
      const sub = !direct && opt.s ? opt.s.find(x => selected.has(x)) : null;
      const base = BASESET.has(id);
      const item = { id, q, sub, base, subs: opt.s || [] };
      if (opt.o) { item.opt = true; item.ok = direct || !!sub || base; nice.push(item); }
      else if (direct || sub || base) { item.ok = true; have.push(item); }
      else need.push(item);
    });
    const core = have.filter(i => !i.base).length + need.length;
    return {
      r, have, need, nice,
      miss: need.length,
      niceMiss: nice.filter(i => !i.ok).length,
      score: core ? (core - need.length) / core : 1,
      core,
    };
  }

  function passFilters(m) {
    if (filterType === MINE) return m.r.own && timeOk(m) && readyOk(m);
    if (filterType !== ALL && m.r.c !== filterType) return false;
    return timeOk(m) && readyOk(m);
  }
  const timeOk = m => !filterTime || m.r.t <= filterTime;
  const readyOk = m => !onlyReady || m.miss === 0;

  /* ---------- отрисовка результатов ---------- */
  function tagList(items, kind) {
    return items.map(i => {
      const name = esc(ingName(i.id));
      const qty = esc(qtyText(i.q) || '');
      if (kind === 'need') {
        return `<li><span class="tag tag--need">${name}${qty ? ` <i>${qty}</i>` : ''}` +
          `<button class="tag__add" type="button" data-tog="${esc(i.id)}" title="${esc(t('i_have_it'))}">+</button></span></li>`;
      }
      if (i.sub) {
        return `<li><span class="tag tag--sub">${esc(ingName(i.sub))} ` +
          `<i>${esc(t('instead_of', ingName(i.id)))}</i></span></li>`;
      }
      const cls = kind === 'nice' ? 'tag--nice' : 'tag--have';
      const note = i.base ? esc(t('basic_item')) : qty;
      return `<li><span class="tag ${cls}">${name}${note ? ` <i>${note}</i>` : ''}` +
        (kind === 'nice' ? `<button class="tag__add" type="button" data-tog="${esc(i.id)}" title="${esc(t('i_have_it'))}">+</button>` : '') +
        `</span></li>`;
    }).join('');
  }

  function card(m) {
    const r = m.r;
    const tone = m.miss === 0 ? 'ready' : m.miss === 1 ? 'one' : 'far';
    const cells = [
      ...m.have.filter(i => !i.base).map(() => '<span class="cell"></span>'),
      ...m.need.map(() => '<span class="cell cell--miss"></span>'),
      ...m.nice.filter(i => !i.ok).map(() => '<span class="cell cell--opt"></span>'),
    ].join('');
    const niceMiss = m.nice.filter(i => !i.ok);
    const niceHave = m.nice.filter(i => i.ok);
    const covText = m.miss === 0
      ? t('cov_all', m.core, plural(m.core, 'p_products'))
      : t('cov_part', m.core - m.miss, m.core, plural(m.core, 'p_products_of'));
    const note = recNote(r);

    return `<article class="recipe recipe--${tone}${r.own ? ' recipe--own' : ''}">
      <header>
        <h3 class="recipe__title">${esc(recName(r))}${r.own ? `<span class="badge">${esc(t('own_short'))}</span>` : ''}</h3>
        <div class="recipe__meta"><span>${esc(t('minutes', r.t))}</span><span>${esc(typeName(r.c))}</span><span>${esc(withN(r.s, 'p_servings'))}</span></div>
      </header>
      <div class="cov">
        <div class="cov__cells">${cells}</div>
        <div class="cov__label">${covText}${niceMiss.length ? t('cov_optional', niceMiss.length, plural(niceMiss.length, 'p_optional')) : ''}</div>
      </div>
      ${m.need.length ? `<div class="lst lst--need"><h4>${esc(t('need_title'))}</h4><ul>${tagList(m.need, 'need')}</ul></div>` : ''}
      ${(m.have.length + niceHave.length) ? `<div class="lst lst--have"><h4>${esc(t('have_title'))}</h4><ul>${tagList(m.have.concat(niceHave), 'have')}</ul></div>` : ''}
      ${niceMiss.length ? `<div class="lst lst--nice"><h4>${esc(t('nice_title'))}</h4><ul>${tagList(niceMiss, 'nice')}</ul></div>` : ''}
      ${note ? `<p class="note">${esc(note)}</p>` : ''}
      <details class="steps"><summary>${esc(t('steps_summary'))}</summary><ol>${recSteps(r).map(s => `<li>${esc(s)}</li>`).join('')}</ol></details>
      ${r.own ? `<div class="recipe__acts">
        <button class="linkbtn" type="button" data-edit="${esc(r.id)}">${esc(t('edit'))}</button>
        <button class="linkbtn" type="button" data-del-recipe="${esc(r.id)}">${esc(t('delete'))}</button></div>` : ''}
    </article>`;
  }

  function group(title, hint, list) {
    if (!list.length) return '';
    return `<section class="group">
      <div class="group__head"><h2>${esc(title)}</h2><span class="rule"></span><span class="n">${list.length}</span></div>
      ${hint ? `<p class="summary">${esc(hint)}</p>` : ''}
      <div class="cards">${list.map(card).join('')}</div>
    </section>`;
  }

  function renderResults() {
    const all = allRecipes();
    const matches = all.map(analyse).sort((a, b) =>
      a.miss - b.miss || b.score - a.score || a.niceMiss - b.niceMiss || a.r.t - b.r.t);

    const real = [...selected].filter(n => !BASESET.has(n));
    if (!real.length) {
      // Корзина пуста, но свои рецепты человек добавил сам — они должны быть видны сразу.
      out.innerHTML = `<div class="blank">
        <h2>${esc(t('empty_title'))}</h2>
        <p>${esc(t('empty_text'))}</p>
        <div class="chips">${POPULAR.map(n =>
          `<button class="pill" type="button" data-tog="${esc(n)}">${esc(ingName(n))}</button>`).join('')}</div>
      </div>` + group(t('group_mine'), '', matches.filter(m => m.r.own));
      return;
    }

    const vis = matches.filter(passFilters);
    const ready = vis.filter(m => m.miss === 0);
    const one = vis.filter(m => m.miss === 1);
    const almost = vis.filter(m => m.miss >= 2 && m.miss <= 3);

    // Хвост списка обрезаем, но свои рецепты из него не выкидываем никогда.
    const far = vis.filter(m => m.miss > 3);
    const keep = new Set(far.filter(m => m.r.own).map(m => m.r.id || m.r.n));
    if (ready.length + one.length + almost.length < 4) {
      far.filter(m => !m.r.own).slice(0, 6).forEach(m => keep.add(m.r.id || m.r.n));
    }
    const rest = far.filter(m => keep.has(m.r.id || m.r.n));

    if (!vis.length) {
      out.innerHTML = `<div class="blank">
        <h2>${esc(t('nothing_title'))}</h2>
        <p>${esc(t('nothing_text'))}</p>
      </div>`;
      return;
    }

    out.innerHTML =
      `<p class="summary">${t('summary', vis.length, plural(vis.length, 'p_recipes'), all.length)}` +
      (ready.length ? t('summary_ready', ready.length) : '') + '.</p>' +
      group(t('group_ready'), '', ready) +
      group(t('group_one'), '', one) +
      group(t('group_almost'), t('group_almost_hint'), almost) +
      group(t('group_more'), t('group_more_hint'), rest);
  }

  out.addEventListener('click', e => {
    const ed = e.target.closest('[data-edit]');
    if (ed) { openRecipeDialog(ed.dataset.edit); return; }

    const del = e.target.closest('[data-del-recipe]');
    if (del) {
      if (del.dataset.armed) {
        customRecipes = customRecipes.filter(r => r.id !== del.dataset.delRecipe);
        store(K.rec, customRecipes);
        renderAll();
      } else {
        out.querySelectorAll('[data-del-recipe][data-armed]').forEach(b => {
          delete b.dataset.armed; b.textContent = t('delete'); b.classList.remove('confirming');
        });
        del.dataset.armed = '1';
        del.textContent = t('delete_confirm');
        del.classList.add('confirming');
      }
      return;
    }

    const b = e.target.closest('[data-tog]');
    if (b) add(b.dataset.tog);
  });

  /* ---------- фильтры ---------- */
  const TIMES = [[0, 'time_any'], [20, 'time_20'], [40, 'time_40'], [60, 'time_60']];

  function renderTabs() {
    const list = [ALL];
    if (customRecipes.length) list.push(MINE);
    list.push(...types());
    typeTabs.innerHTML = list.map(c => {
      const label = c === ALL ? t('filter_all') : c === MINE ? t('filter_mine') : typeName(c);
      return `<button class="tab${c === filterType ? ' is-on' : ''}" type="button" ` +
        `data-type="${esc(c)}">${esc(label)}</button>`;
    }).join('');
    timeTabs.innerHTML = TIMES.map(([v, key]) =>
      `<button class="tab${v === filterTime ? ' is-on' : ''}" type="button" data-time="${v}">${esc(t(key))}</button>`).join('');
  }

  typeTabs.addEventListener('click', e => {
    const b = e.target.closest('[data-type]');
    if (!b) return;
    filterType = b.dataset.type;
    renderTabs();
    renderResults();
  });
  timeTabs.addEventListener('click', e => {
    const b = e.target.closest('[data-time]');
    if (b) { filterTime = +b.dataset.time; renderTabs(); renderResults(); }
  });
  onlyReadyBox.addEventListener('change', () => { onlyReady = onlyReadyBox.checked; renderResults(); });

  /* ---------- диалог: свой рецепт ---------- */
  const dlgRecipe = $('dlgRecipe'), rRows = $('rRows'), rMsg = $('rMsg');

  function rowHTML(v) {
    v = v || {};
    return `<div class="row">
      <input class="r-i" list="ingList" placeholder="${esc(t('ph_product'))}" autocomplete="off" value="${esc(v.i || '')}">
      <input class="r-q" placeholder="${esc(t('ph_qty'))}" autocomplete="off" value="${esc(v.q || '')}">
      <input class="r-s" list="ingList" placeholder="${esc(t('ph_sub'))}" autocomplete="off" value="${esc(v.s || '')}">
      <label class="opt"><input type="checkbox" class="r-o"${v.o ? ' checked' : ''}> ${esc(t('without_it'))}</label>
      <button class="row__del" type="button" title="${esc(t('remove_row'))}" aria-label="${esc(t('remove_row'))}">×</button>
    </div>`;
  }

  function openRecipeDialog(id) {
    editingId = id || null;
    const r = id ? findRecipe(id) : null;
    rMsg.textContent = '';
    $('rHead').textContent = r ? t('dlg_edit_recipe') : t('dlg_new_recipe');
    $('rDelete').hidden = !r;
    $('rName').value = r ? r.n : '';
    $('rType').value = r ? typeName(r.c) : '';
    $('rTime').value = r ? r.t : 30;
    $('rServ').value = r ? r.s : 2;
    $('rNote').value = r && r.note ? r.note : '';
    $('rSteps').value = r ? r.st.join('\n') : '';
    rRows.innerHTML = r
      ? r.g.map(([i, q, o]) => rowHTML({
          i: ingName(i), q, o: o && o.o, s: (o && o.s || []).map(ingName).join(', '),
        })).join('')
      : rowHTML() + rowHTML() + rowHTML();
    dlgRecipe.showModal();
    $('rName').focus();
  }

  $('newRecipeBtn').addEventListener('click', () => openRecipeDialog(null));
  $('rAddRow').addEventListener('click', () => {
    rRows.insertAdjacentHTML('beforeend', rowHTML());
    rRows.lastElementChild.querySelector('.r-i').focus();
  });
  rRows.addEventListener('click', e => {
    if (!e.target.closest('.row__del')) return;
    if (rRows.children.length > 1) e.target.closest('.row').remove();
    else rRows.querySelectorAll('input').forEach(i => { i.value = ''; i.checked = false; });
  });
  $('rCancel').addEventListener('click', () => dlgRecipe.close());
  $('rDelete').addEventListener('click', () => {
    customRecipes = customRecipes.filter(r => r.id !== editingId);
    store(K.rec, customRecipes);
    dlgRecipe.close();
    renderAll();
  });

  $('recipeForm').addEventListener('submit', e => {
    e.preventDefault();
    const name = $('rName').value.trim();
    const steps = $('rSteps').value.split('\n').map(s => s.trim()).filter(Boolean);

    const rows = [...rRows.querySelectorAll('.row')].map(row => ({
      i: row.querySelector('.r-i').value.trim(),
      q: row.querySelector('.r-q').value.trim(),
      s: row.querySelector('.r-s').value.split(',').map(x => x.trim()).filter(Boolean),
      o: row.querySelector('.r-o').checked,
    })).filter(r => r.i);

    if (!name) return fail(t('err_name'));
    if (!rows.length) return fail(t('err_products'));
    if (!steps.length) return fail(t('err_steps'));
    if (rows.every(r => r.o)) return fail(t('err_all_optional'));

    const dup = allRecipes().find(r => norm(recName(r)) === norm(name) && r.id !== editingId);
    if (dup) return fail(t('err_duplicate', recName(dup)));

    /* Знакомые названия — хоть по-русски, хоть по-английски — приводим к ключу каталога,
       незнакомые становятся вашими продуктами. */
    const resolve = n => canonIng(n) || addIngredient(n, OWN_CAT) || n;
    const g = rows.map(r => {
      const opts = {};
      if (r.o) opts.o = 1;
      const key = resolve(r.i);
      const subs = r.s.map(resolve).filter(s => s !== key);
      if (subs.length) opts.s = subs;
      const item = [key, r.q || t('to_taste')];
      if (Object.keys(opts).length) item.push(opts);
      return item;
    });

    const rec = {
      id: editingId || 'u' + Date.now().toString(36),
      own: true,
      n: name,
      c: canonType($('rType').value.trim() || t('default_type')),
      t: clamp(parseInt($('rTime').value, 10) || 30, 1, 600),
      s: clamp(parseInt($('rServ').value, 10) || 2, 1, 20),
      g, st: steps,
    };
    const note = $('rNote').value.trim();
    if (note) rec.note = note;

    const i = customRecipes.findIndex(r => r.id === rec.id);
    if (i >= 0) customRecipes[i] = rec; else customRecipes.unshift(rec);
    store(K.rec, customRecipes);

    dlgRecipe.close();
    renderAll();

    function fail(m) { rMsg.textContent = m; }
  });

  /* ---------- диалог: свой продукт ---------- */
  const dlgIng = $('dlgIng'), iMsg = $('iMsg');

  function renderMine() {
    const box = $('iMine');
    $('iMineWrap').hidden = !customIng.length;
    box.innerHTML = customIng.map(({ name, cat }) =>
      `<div class="mine__row">${esc(name)} <span class="m">${esc(sectionName(cat))}</span>
        <span class="spacer"></span>
        <button class="linkbtn" type="button" data-del-ing="${esc(name)}">${esc(t('delete'))}</button></div>`).join('');
  }

  function openIngDialog() {
    iMsg.textContent = '';
    $('iName').value = '';
    $('iCat').innerHTML = [OWN_CAT, ...CATALOG.map(([c]) => c)]
      .map(c => `<option value="${esc(c)}">${esc(sectionName(c))}</option>`).join('');
    renderMine();
    dlgIng.showModal();
    $('iName').focus();
  }

  $('newIngBtn').addEventListener('click', openIngDialog);
  $('iCancel').addEventListener('click', () => dlgIng.close());
  $('iMine').addEventListener('click', e => {
    const b = e.target.closest('[data-del-ing]');
    if (b) deleteIngredient(b.dataset.delIng);
  });

  $('ingForm').addEventListener('submit', e => {
    e.preventDefault();
    const name = $('iName').value.trim();
    if (!name) { iMsg.textContent = t('err_ing_empty'); return; }
    const exists = canonIng(name);
    if (exists) {
      iMsg.textContent = t('err_ing_exists', ingName(exists));
      return;
    }
    addIngredient(name, $('iCat').value);
    selected.add(name); saveBasket();
    iMsg.textContent = '';
    $('iName').value = '';
    $('iName').focus();
    renderAll();
    renderMine();
  });

  /* Сообщения о продуктах показываем в их же диалоге — открываем его, если он закрыт. */
  function alertBox(text) {
    if (!dlgIng.open) openIngDialog();
    iMsg.textContent = text;
  }

  /* ---------- диалог: мои данные ---------- */
  const dlgData = $('dlgData'), dText = $('dText'), dMsg = $('dMsg');

  const dataSummary = () => t('backup_summary', customRecipes.length, customIng.length, selected.size);

  function openDataDialog() {
    dMsg.textContent = '';
    $('dSummary').textContent = dataSummary();
    dText.value = JSON.stringify({ v: 1, ing: customIng, recipes: customRecipes, basket: [...selected] }, null, 2);
    dlgData.showModal();
  }

  $('dataBtn').addEventListener('click', openDataDialog);
  $('dClose').addEventListener('click', () => dlgData.close());

  $('dCopy').addEventListener('click', () => {
    dText.select();
    let ok = false;
    try { ok = document.execCommand('copy'); } catch (e) {}
    if (!ok && navigator.clipboard) {
      navigator.clipboard.writeText(dText.value)
        .then(() => { dMsg.textContent = t('copied'); })
        .catch(() => { dMsg.textContent = t('copy_manual'); });
      return;
    }
    dMsg.textContent = ok ? t('copied') : t('copy_manual');
  });

  $('dDownload').addEventListener('click', () => {
    try {
      const blob = new Blob([dText.value], { type: 'application/json' });
      const a = document.createElement('a');
      a.href = URL.createObjectURL(blob);
      a.download = 'moi-recepty.json';
      document.body.appendChild(a);
      a.click();
      a.remove();
      setTimeout(() => URL.revokeObjectURL(a.href), 1000);
      dMsg.textContent = '';
    } catch (e) {
      dMsg.textContent = t('download_failed');
    }
  });

  $('dLoad').addEventListener('click', () => {
    let data;
    try { data = JSON.parse(dText.value); }
    catch (e) { dMsg.textContent = t('import_bad'); return; }

    const incIng = Array.isArray(data.ing) ? data.ing.filter(x => x && x.name) : [];
    const incRec = Array.isArray(data.recipes)
      ? data.recipes.filter(r => r && r.n && Array.isArray(r.g) && Array.isArray(r.st)) : [];
    if (!incIng.length && !incRec.length) { dMsg.textContent = t('import_empty'); return; }

    let addedI = 0, addedR = 0;
    incIng.forEach(({ name, cat }) => {
      if (![...ING.keys(), ...customIng.map(i => i.name)].some(n => norm(n) === norm(name))) {
        customIng.push({ name, cat: cat || OWN_CAT }); addedI++;
      }
    });
    incRec.forEach(r => {
      const id = r.id || 'u' + Math.random().toString(36).slice(2, 9);
      const i = customRecipes.findIndex(x => x.id === id || norm(x.n) === norm(r.n));
      const rec = { ...r, id, own: true, c: r.c || 'Основное', t: r.t || 30, s: r.s || 2 };
      if (i >= 0) customRecipes[i] = rec; else { customRecipes.unshift(rec); addedR++; }
    });
    if (Array.isArray(data.basket)) data.basket.forEach(n => selected.add(n));

    store(K.ing, customIng); store(K.rec, customRecipes); saveBasket();
    renderAll();
    dMsg.textContent = t('import_ok', addedR, addedI);
    $('dSummary').textContent = dataSummary();
  });

  /* ---------- язык интерфейса ---------- */
  function applyStaticText() {
    document.title = t('page_title');
    if (document.documentElement) document.documentElement.lang = lang;
    document.querySelectorAll('[data-t]').forEach(el => { el.textContent = t(el.dataset.t); });
    document.querySelectorAll('[data-t-ph]').forEach(el => { el.placeholder = t(el.dataset.tPh); });
    document.querySelectorAll('[data-t-aria]').forEach(el => { el.setAttribute('aria-label', t(el.dataset.tAria)); });
  }

  $('langBtn').addEventListener('click', () => {
    lang = lang === 'ru' ? 'en' : 'ru';
    UI = I18N.ui[lang];
    store(K.lang, lang);
    applyStaticText();
    applyTheme(theme);
    renderAll();
  });

  /* ---------- тема ---------- */
  const themeBtn = $('themeBtn');
  const prefersDark = () => window.matchMedia('(prefers-color-scheme: dark)').matches;
  let theme = null;
  try { theme = localStorage.getItem(K.theme); } catch (e) {}
  if (theme) theme = theme.replace(/"/g, '');

  function applyTheme(mode) {
    if (mode) document.documentElement.setAttribute('data-theme', mode);
    else document.documentElement.removeAttribute('data-theme');
    themeBtn.textContent = (mode ? mode === 'dark' : prefersDark()) ? t('theme_to_light') : t('theme_to_dark');
  }
  applyTheme(theme);
  themeBtn.addEventListener('click', () => {
    theme = (theme ? theme === 'dark' : prefersDark()) ? 'light' : 'dark';
    try { localStorage.setItem(K.theme, theme); } catch (e) {}
    applyTheme(theme);
  });

  /* ---------- старт ---------- */
  applyStaticText();
  renderAll();
})();

